import json

def build_system(policy_text, customer):
    profile = {"tier": customer.tier, "region": customer.region,
               "flags": {f for f in customer.flags}}
    return [
        {"type": "text", "text": json.dumps(profile, default=list) + "\n\n" + policy_text,
         "cache_control": {"type": "ephemeral"}},
    ]
